def _append_line(self, session_id: str, record: dict) -> None:
    with self._path(session_id).open("w", encoding="utf-8") as handle:
        handle.write(json.dumps(record, ensure_ascii=False) + "\n")

remaining = [
    p
    for p in existing
    if not (p.statement == statement and p.kind == "dislike")
]

def _safe_name(raw: str) -> str:
    """文件名清洗，避免路径穿越。"""
    return raw or "anonymous"

__table_args__ = (
