)

document_id = md_file.stem
if document_id in existing:
    continue

await self._order_repo.save(order)

if idempotency_key and self._idempotency is not None:
    claimed = await self._idempotency.record(idempotency_key, order.order_id)

try:
    result = await self._client.xautoclaim(
        _STREAM, _GROUP, consumer_name, min_idle_time=idle_ms, count=10,
    )
except Exception:  # noqa: BLE001
    return []

if not batches:
    in_flight = {task for task in in_flight if not task.done()}
    continue

@lru_cache(maxsize=1)
def load_prompts() -> dict:
    with open(PROMPTS_PATH, encoding="utf-8") as f:
        return yaml.safe_load(f)

rerank_scores = await self._reranker.rerank(spec.normalized_query, documents)
reranked = [
    (rerank_scores[i], product)
    for i, (_, product) in enumerate(scored)
]

def _within_price_cap(self, product: Product, spec: ProductSearchSpec) -> bool:
    if spec.price_max_major is None:
        return True
    primary_in_target = self._tariff.rates.convert(product.primary_sku().price, spec.target_currency)
    return primary_in_target.to_major_units() <= spec.price_max_major

for card in cards:
    for sku in card.skus:
        if sku["sku_id"] in current:
            sku["stock"] = current[sku["sku_id"]]

for start in range(0, len(texts), _MAX_BATCH):
    chunk = texts[start : start + _MAX_BATCH]
    vectors.extend(await self._embed_chunk(client, chunk))

if top_k <= 0:
    # 只保留安全底线，正向偏好全部让位
    return dislikes

if norm_left == 0 or norm_right == 0:
    return 0.0
return dot / (norm_left * norm_right)
